parameters.jsonBody:
={
  "type": "message",
  "attachments": [
    {
      "contentType": "application/vnd.microsoft.card.adaptive",
      "content": {
        "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
        "type": "AdaptiveCard",
        "version": "1.4",
        "body": [
          {
            "type": "TextBlock",
            "text": "🥚 LEMBRETE: COMPRA DE OVOS 🥚",
            "weight": "Bolder",
            "size": "Large",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "👥 Responsáveis da semana",
            "weight": "Bolder",
            "spacing": "Medium",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "{{ $json.person1_name }} e {{ $json.person2_name }}",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "⏰ Hoje é o dia!",
            "weight": "Bolder",
            "spacing": "Medium",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "Não esqueçam de comprar a cartela de 30 ovos combinada na sexta 🙏",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "🔁 Ciclo atual: #{{ $json.cycle_number }}",
            "spacing": "Medium",
            "isSubtle": true,
            "wrap": true
          }
        ]
      }
    }
  ]
}
